import os,sys,json,pathlib,hashlib,base64,datetime,subprocess,re,time,signal,stat,traceback
ROOT=pathlib.Path('/Users/me/Developer/capturesuite-recorded-report-receiving-c945953fdeb7')
PAYLOAD=json.loads(base64.b64decode(''))
MIB=1024**2
def now():return datetime.datetime.now(datetime.timezone.utc).isoformat()
def pin(b):return {'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest(),'git_blob':hashlib.sha1(b'blob '+str(len(b)).encode()+b'\0'+b).hexdigest()}
def ident(p):
 s=p.stat();return {**pin(p.read_bytes()),'mode':format(stat.S_IMODE(s.st_mode),'04o'),'mtime_ns':str(s.st_mtime_ns)}
def owned(skip_browser=True):
 total=0;alloc=0
 if ROOT.exists():
  for base,dirs,names in os.walk(ROOT):
   if skip_browser and pathlib.Path(base)==ROOT:dirs[:]=[x for x in dirs if x!='browser']
   for name in names:
    p=pathlib.Path(base)/name
    if p.is_symlink():continue
    s=p.stat();total+=s.st_size;alloc+=s.st_blocks*512
 return {'bytes':total,'allocated_bytes':alloc}
def guard(label):
 v=subprocess.run(['/usr/bin/vm_stat'],capture_output=True,text=True,check=True,timeout=5).stdout
 page=int(re.search(r'page size of (\d+) bytes',v).group(1))
 mem=sum(int(re.search(r'^'+re.escape(k)+r':\s+(\d+)',v,re.M).group(1)) for k in ('Pages free','Pages inactive','Pages speculative'))*page
 s=os.statvfs('/Users/me')
 out={'label':label,'time_utc':now(),'disk_free_bytes':s.f_bavail*s.f_frsize,'conservative_memory_bytes':mem,'owned':owned(),
      'disk_floor_bytes':256*MIB,'memory_floor_bytes':2*1024*MIB,'static_cap_bytes':2*MIB}
 out['admitted']=out['disk_free_bytes']>=256*MIB and mem>=2*1024*MIB and max(out['owned'].values())<=2*MIB
 if not out['admitted']:raise RuntimeError('frozen Mac guard refusal: '+json.dumps(out))
 return out
def write_new(name,b):
 p=ROOT/name
 if len(b)>MIB:raise RuntimeError('per-file cap')
 with p.open('xb') as f:
  if f.write(b)!=len(b):raise RuntimeError('short owned write')
  f.flush();os.fsync(f.fileno())
 p.chmod(0o444)
 return ident(p)
record={'schema':'capturesuite-mac-actual-outer-execution-v1','started_at':now(),'controller_pid':os.getpid(),'contract':PAYLOAD['contract'],
        'node_child_started':False,'guards':[],'error':None}
node=None
try:
 record['guards'].append(guard('before-exclusive-mac-materialization'))
 if os.path.lexists(ROOT):raise RuntimeError('exclusive receiving root already exists')
 for f in PAYLOAD['files']:
  if pathlib.PurePosixPath(f['path']).name!=f['path'] or pin(f['content'].encode())!=f['pin']:raise RuntimeError('payload path/pin')
 for key,expected in PAYLOAD['runtime'].items():
  p=pathlib.Path(expected['path'])
  if p.stat().st_size!=expected['bytes'] or hashlib.sha256(p.read_bytes()).hexdigest()!=expected['sha256']:raise RuntimeError('runtime identity: '+key)
 os.umask(0o077);ROOT.mkdir(mode=0o700)
 files={f['path']:write_new(f['path'],f['content'].encode()) for f in PAYLOAD['files']}
 record['initial_files']=files
 preparation={'schema':'capturesuite-mac-physical-file-preparation-v1','time_utc':now(),'root':str(ROOT),'files':files,
              'admission':record['guards'][0],'runtime_preflight':PAYLOAD['runtime'],'report_regenerated':False,
              'browser_execution_before_record':False,'controller_pid':os.getpid()}
 write_new('SOURCE-PREPARATION.json',(json.dumps(preparation,ensure_ascii=False,indent=2)+'\n').encode())
 record['guards'].append(guard('before-owned-node-browser-controller'))
 record['argv']=['/opt/homebrew/bin/node',str(ROOT/'receiver.mjs')];record['cwd']='/tmp'
 outpath=ROOT/'node.stdout.txt';errpath=ROOT/'node.stderr.txt'
 with outpath.open('xb') as out,errpath.open('xb') as err:
  t=time.monotonic();node=subprocess.Popen(record['argv'],cwd='/tmp',stdin=subprocess.DEVNULL,stdout=out,stderr=err,start_new_session=True)
  record['node_child_started']=True;record['node_pid']=node.pid
  print(json.dumps({'stage_prepared':True,'root':str(ROOT),'controller_pid':os.getpid(),'node_pid':node.pid,'guards':record['guards']}),flush=True)
  try:rc=node.wait(timeout=195)
  except subprocess.TimeoutExpired:
   record['outer_timeout']=True;os.killpg(node.pid,signal.SIGTERM)
   try:rc=node.wait(timeout=2)
   except subprocess.TimeoutExpired:os.killpg(node.pid,signal.SIGKILL);rc=node.wait()
  record['node_elapsed_seconds']=time.monotonic()-t
  record['node_wait_exit']=rc;record['node_poll_exit']=node.poll();record['node_reaped_by_wait']=True
 for p in (outpath,errpath):p.chmod(0o444)
 record['stdout']={'pin':ident(outpath),'text':outpath.read_bytes().decode('utf-8')}
 record['stderr']={'pin':ident(errpath),'text':errpath.read_bytes().decode('utf-8')}
 after={name:ident(ROOT/name) for name in files}
 record['final_input_files']=after;record['all_initial_files_unchanged']=after==files
 record['guards'].append(guard('after-owned-node-wait'))
 record['accepted']=rc==0 and record['all_initial_files_unchanged']
except BaseException as e:
 record['accepted']=False;record['error']={'type':type(e).__name__,'message':str(e),'traceback':traceback.format_exc()}
 if node is not None and node.poll() is None:
  os.killpg(node.pid,signal.SIGTERM)
  try:node.wait(timeout=2)
  except subprocess.TimeoutExpired:os.killpg(node.pid,signal.SIGKILL);node.wait()
  record['node_wait_exit']=node.returncode;record['node_poll_exit']=node.poll();record['node_reaped_by_wait']=True
finally:
 record['finished_at']=now();record['scope']='Exact physical HTML transfer and one private browser controller; no CaptureSuite Python import or output regeneration.'
 if ROOT.exists():
  try:record_pin=write_new('OUTER-EXECUTION.json',(json.dumps(record,ensure_ascii=False,indent=2)+'\n').encode())
  except BaseException as e:record_pin=None;record['outer_receipt_write_error']=str(e)
 else:record_pin=None
 print(json.dumps({'outer_complete':True,'accepted':record.get('accepted',False),'root':str(ROOT),'controller_pid':os.getpid(),
                   'node_pid':record.get('node_pid'),'node_wait_exit':record.get('node_wait_exit'),'node_reaped_by_wait':record.get('node_reaped_by_wait'),
                   'error':record['error'],'outer_receipt':record_pin,'full_record_if_unwritten':record if record_pin is None else None}),flush=True)
raise SystemExit(0 if record.get('accepted',False) else 1)
